    # Step 1: Build an interval tree
    class IntervalTreeNode:
        def __init__(self, start, end):
            self.start = start
            self.end = end
            self.left = None
            self.right = None
            self.intervals = []

    def build_tree(intervals, start, end):
        if not intervals:
            return None

        mid = (start + end) // 2
        root = IntervalTreeNode(mid, mid)
        for interval in intervals:
            if interval[0] <= mid <= interval[1]:
                root.intervals.append(interval)
        left_intervals = [i for i in intervals if i[1] < mid]
        right_intervals = [i for i in intervals if i[0] > mid]
        root.left = build_tree(left_intervals, start, mid - 1)
        root.right = build_tree(right_intervals, mid + 1, end)
        return root

    # Step 2: Query the interval tree to collect all overlapping intervals
    def query_tree(node, current_start, result):
        if not node:
            return

        # Check if current node's interval overlaps with current_start
        if node.start <= current_start <= node.end:
            # Collect all intervals in this node
            for interval in node.intervals:
                if interval[0] <= current_start <= interval[1]:
                    result.append(interval)
            # Recursively check left and right
            query_tree(node.left, current_start, result)
            query_tree(node.right, current_start, result)
        elif current_start < node.start:
            query_tree(node.left, current_start, result)
        else:
            query_tree(node.right, current_start, result)

    # Step 3: Sort intervals by start
