    if not intervals:
        return []

    # Build an interval tree
    tree = defaultdict(list)
    for start, end in intervals:
        tree[start].append(end)

    # Sort the start points
    sorted_starts = sorted(tree.keys())

    merged = []
    for start in sorted_starts:
        # Find the max end for this start
        max_end = max(tree[start])
        # Check if we can merge with the last merged interval
        if merged and merged[-1][1] >= start - 1:
            merged[-1][1] = max(merged[-1][1], max_end)
        else:
            merged.append([start, max_end])

    return merged

