class IntervalTreeNode:
    def __init__(self, start, end, left=None, right=None, interval=None):
        self.start = start
        self.end = end
        self.left = left
        self.right = right
        self.interval = interval

class IntervalTree:
    def __init__(self, intervals):
        self.root = self.build_tree(intervals)

    def build_tree(self, intervals):
        if not intervals:
            return None
        mid = len(intervals) // 2
        node = IntervalTreeNode(intervals[mid][0], intervals[mid][1], interval=intervals[mid])
        node.left = self.build_tree(intervals[:mid])
        node.right = self.build_tree(intervals[mid+1:])
        return node

    def insert(self, node, interval):
        if not node:
            return IntervalTreeNode(interval[0], interval[1], interval=interval)
        if interval[1] < node.start:
            node.left = self.insert(node.left, interval)
        elif interval[0] > node.end:
            node.right = self.insert(node.right, interval)
        else:
            node.interval = interval
        return node

    def query(self, node, result):
        if not node:
            return
        result.append(node.interval)
        self.query(node.left, result)
        self.query(node.right, result)

