class IntervalTree:
    def __init__(self, intervals):
        self.root = self.build_tree(intervals)

    def build_tree(self, intervals):
        if not intervals:
            return None
        mid = len(intervals) // 2
        node = IntervalTreeNode(intervals[mid][0], intervals[mid][1])
        node.intervals = intervals
        node.left = self.build_tree(intervals[:mid])
        node.right = self.build_tree(intervals[mid+1:])
        return node

    def query(self, start, end):
        return self._query(self.root, start, end)

    def _query(self, node, start, end):
        if not node:
            return []
        result = []
        if node.start <= end and node.end >= start:
            result.extend(node.intervals)
            if node.left:
                result.extend(self._query(node.left, start, end))
            if node.right:
                result.extend(self._query(node.right, start, end))
        return result

