    # Sort intervals by start time
    intervals.sort()

    # Build interval tree
    tree = IntervalTree(intervals)

    # Query the tree for all intervals overlapping with the first one
    merged = [intervals[0]]
    for i in range(1, len(intervals)):
        # Find all intervals that overlap with the current merged interval
        overlapping = tree.query(merged[-1][0], merged[-1][1])
        if overlapping:
            new_start = min(merged[-1][0], overlapping[0][0])
            new_end = max(merged[-1][1], overlapping[-1][1])
            merged[-1] = [new_start, new_end]
        else:
            merged.append(intervals[i])

    # Sort the final result by start time
    merged.sort()
    return merged

